pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint256 extra) public {
        vm.assume(depositAmount > 0);
        uint256 amount = bound(withdrawAmount, 0, depositAmount);
        address actor = address(0xBEEF);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        vm.prank(actor);
        c.withdraw(amount);
        // withdrawing more than the remaining balance must revert (balance was decremented)
        extra = bound(extra, 1, depositAmount - amount + 1);
        bool reverted;
        vm.prank(actor);
        try c.withdraw(depositAmount - amount + extra) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}

